def check_equation(x, y, z):
    # Equation: x^3 + y^3 + z^3 - x^2*y^2*z^2 = 0
    return x**3 + y**3 + z**3 - (x**2 * y**2 * z**2)

solutions = []
for z in range(1, 6):  # z <= 5
    for y in range(1, z + 1):  # y <= z
        for x in range(1, y + 1):  # x <= y
            if check_equation(x, y, z) == 0:
                solutions.append((x, y, z))

print(solutions)

